    # If empty or single interval, return as is (but copy to avoid mutation)
    if not intervals:
        return []
    # Sort intervals by start
    sorted_ints = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = []
    for start, end in sorted_ints:
        if not merged:
            merged.append([start, end])
        else:
            last = merged[-1]
            # If current starts before or at last's end (touching), merge
            if start <= last[1]:
                # Extend the last interval's end if needed
                last[1] = max(last[1], end)
            else:
                merged.append([start, end])
    return merged
