def solve(mat):
    # Determinant using recursive Laplace expansion.
    # Empty matrix has determinant 1.
    if not mat:
        return 1
    n = len(mat)
    # Validate square matrix
    for row in mat:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Base cases
    if n == 1:
        return mat[0][0]
    if n == 2:
        return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
    det = 0
    for col in range(n):
        # Build minor matrix
        minor = [row[:col] + row[col+1:] for row in mat[1:]]
        sign = -1 if col % 2 else 1
        det += sign * mat[0][col] * solve(minor)
    return det

def solve(intervals):
    """Merge overlapping or touching intervals.
    Handles intervals where start may be greater than end by swapping.
    Returns a new list of [start, end] intervals sorted by start.
    """
    # Defensive copy and normalization
    norm = []
    for iv in intervals:
        # Accept any iterable of length 2
        try:
            a, b = iv[0], iv[1]
        except Exception:
            # If not indexable, try unpacking
            a, b = iv
        if a <= b:
            norm.append([a, b])
        else:
            norm.append([b, a])
    if not norm:
        return []
    # Sort by start then end
    norm.sort(key=lambda x: (x[0], x[1]))
    merged = [norm[0].copy()]
    for start, end in norm[1:]:
        last = merged[-1]
        if start <= last[1]:  # overlap or touch
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

