def solve(s: str) -> int:
    """Return length of the longest substring without repeating characters.

    Uses a sliding window with a dictionary mapping characters to their most recent index.
    """
    # Edge case
    if not s:
        return 0
    last_index = {}
    max_len = 0
    start = 0  # start index of current window
    for i, ch in enumerate(s):
        # If character seen and within current window, move start right after previous occurrence
        if ch in last_index and last_index[ch] >= start:
            start = last_index[ch] + 1
        last_index[ch] = i
        # Update max length
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

