def solve(path):
    """Simplify a Unix-style absolute path.
    Resolves "." (current directory) and ".." (parent directory),
    collapses multiple slashes, and removes any trailing slash
    except for the root which remains '/'.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

def solve(path: str) -> str:
    """Simplify a Unix absolute path.

    Args:
        path: absolute path starting with '/'.
    Returns:
        Simplified canonical path.
    """
    # Split by '/', ignore empty and '.' parts
    parts = []
    for token in path.split('/'):
        if token == '' or token == '.':
            continue
        if token == '..':
            if parts:
                parts.pop()
            # if no parts, stay at root
        else:
            parts.append(token)
    simplified = '/' + '/'.join(parts)
    return simplified

