def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest ending value of an increasing subseq of length i+1
    for x in nums:
        # find leftmost index where x can extend
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

