def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount*.
    *coins* is a list of positive integers, unlimited supply.
    If it is impossible, return -1.
    """
    # Guard against invalid inputs
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # DP array where dp[i] = min coins to make i, initialize to a large number
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive coin values
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

