def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited
    supply of the given *coins*. If impossible, return -1.
    Uses a DP bottom‑up approach. Complexity O(amount * len(coins)).
    """
    # Filter out non‑positive coin values to avoid infinite loops
    coins = [c for c in coins if c > 0]
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with a sentinel larger than any possible answer
    INF = amount + 1  # more than max possible coins (using 1‑value coins)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

