def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of horizontally or vertically adjacent cells with a non‑zero value.
    Empty or missing grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if grid[0] else 0
    if m == 0:
        return 0
    visited = [[False] * m for _ in range(n)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    islands = 0
    for i in range(n):
        for j in range(m):
            # treat any non‑zero / truthy value as land
            if grid[i][j] and not visited[i][j]:
                islands += 1
                # BFS/DFS to mark the whole island
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    r, c = stack.pop()
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
