def solve(grid):
    if not grid:
        return -1
    n=len(grid)
    m=len(grid[0])
    if grid[0][0]==1 or grid[n-1][m-1]==1:
        return -1
    if n==1 and m==1:
        return 0
    from collections import deque
    q=deque([(0,0,0)])
    visited=[[False]*m for _ in range(n)]
    visited[0][0]=True
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    while q:
        r,c,d=q.popleft()
        nd=d+1
        for dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<n and 0<=nc<m and not visited[nr][nc] and grid[nr][nc]==0:
                if nr==n-1 and nc==m-1:
                    return nd
                visited[nr][nc]=True
                q.append((nr,nc,nd))
    return -1

