def solve(a, x):
    """Return the leftmost index to insert *x* into sorted list *a*.
    Equivalent to Python's bisect_left.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(a, x):
    """Return the leftmost index to insert x into sorted list a.
    Equivalent to bisect.bisect_left.
    """
    import bisect
    return bisect.bisect_left(a, x)

