def solve(n, edges):
    """Return the shortest path weight from node 0 to node n-1 in an undirected weighted graph.
    If n == 1, distance is 0. If the target is unreachable, return -1.
    edges is a list of [a, b, w] with w > 0.
    """
    if n == 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    import heapq
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (distance, node)
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

